    if not input_data:
        return

    n = int(input_data[0])
    idx = 1

    board = []
    for _ in range(n):
        row = [int(x) for x in input_data[idx:idx + n]]
        idx += n
        board.append(row)

    for i in range(1, n):
        for j in range(1, n):
            zeros = 0
            ones = 0
            for val in (board[i][j - 1], board[i - 1][j - 1], board[i - 1][j]):
                if val == 0:
                    zeros += 1
                else:
                    ones += 1
            if zeros > ones:
                board[i][j] = 1
            else:
                board[i][j] = 0

    print(board[n - 1][n - 1])

if __name__ == '__main__':
    main()
